from queueing import payload


def submit(owner, enqueue, batch_size=20):
    if isinstance(batch_size, bool) or not isinstance(batch_size, int):
        raise ValueError("batch_size must be an integer between 1 and 100")
    if not 1 <= batch_size <= 100:
        raise ValueError("batch_size must be an integer between 1 and 100")
    return enqueue(payload(owner, batch_size))

def execute(task, process):
    batch_size = task.get("batch_size", 20)
    return process(task["owner"], batch_size)

from api import submit
from queueing import payload
from worker import execute


def test_default_batch_size():
    seen = {}
    def enqueue(p):
        seen["p"] = p
        return p
    submit("alice", enqueue)
    assert seen["p"] == {"owner": "alice", "batch_size": 20}


def test_custom_batch_size():
    seen = {}
    def enqueue(p):
        seen["p"] = p
        return p
    submit("bob", enqueue, batch_size=50)
    assert seen["p"] == {"owner": "bob", "batch_size": 50}


def test_bool_rejected_before_enqueue():
    calls = []
    def enqueue(p):
        calls.append(p)
        return p
    try:
        submit("carol", enqueue, batch_size=True)
    except ValueError:
        pass
    else:
        raise AssertionError("bool should raise ValueError")
    assert calls == [], "enqueue must not be called before validation"


def test_invalid_values_rejected_before_enqueue():
    for bad in (0, 101, "20", None, 1.5, [20]):
        calls = []
        def enqueue(p):
            calls.append(p)
            return p
        try:
            submit("dave", enqueue, batch_size=bad)
        except ValueError:
            pass
        else:
            raise AssertionError(f"{bad!r} should raise ValueError")
        assert calls == [], f"enqueue must not be called for {bad!r}"


def test_worker_uses_batch_size():
    calls = []
    def process(owner, batch_size):
        calls.append((owner, batch_size))
        return (owner, batch_size)
    result = execute({"owner": "erin", "batch_size": 42}, process)
    assert result == ("erin", 42)
    assert calls == [("erin", 42)]


